#include <stdio.h>
#include <stdlib.h>
#include <string.h>
int isfib(long long v){long long a=1,b=1;while(b<v){long long t=a+b;a=b;b=t;}return b==v;}int main(void){int n,i;static long long a[500005];if(scanf("%d",&n)!=1)return 1;for(i=0;i<n;i++)scanf("%lld",&a[i]);long long m=-1;for(i=0;i<n;i++){long long x=a[i];if(isfib(x))if(x>m)m=x;}printf("%lld\n",m);return 0;}
